use nih_plug::prelude::*;
use std::sync::Arc;
mod dsp;
use dsp::{Biquad,BiquadKind};

pub struct EmberEq { params:Arc<EmberParams>, sample_rate:f32, left:[Biquad;6], right:[Biquad;6] }
#[derive(Params)] pub struct EmberParams { #[id="bypass"] pub bypass:BoolParam, #[id="out_gain"] pub output_gain:FloatParam, #[nested(array, group="Bands")] pub bands:[BandParams;6] }
#[derive(Params)] pub struct BandParams { #[id="enabled"] pub enabled:BoolParam, #[id="freq"] pub frequency:FloatParam, #[id="gain"] pub gain:FloatParam, #[id="q"] pub q:FloatParam, #[id="kind"] pub kind:EnumParam<FilterKind> }
#[derive(Enum,Debug,Clone,Copy,PartialEq,Eq)] pub enum FilterKind { #[name="Bell"] Bell, #[name="Low Shelf"] LowShelf, #[name="High Shelf"] HighShelf, #[name="Low Cut"] LowCut, #[name="High Cut"] HighCut }

impl Default for EmberParams { fn default()->Self { let f=[55.,140.,500.,1800.,6500.,14000.]; Self{bypass:BoolParam::new("Bypass",false),output_gain:FloatParam::new("Output",0.,FloatRange::Linear{min:-18.,max:18.}).with_unit(" dB").with_smoother(SmoothingStyle::Logarithmic(20.)),bands:std::array::from_fn(|i|BandParams{enabled:BoolParam::new(format!("Band {} On",i+1),true),frequency:FloatParam::new(format!("Band {} Frequency",i+1),f[i],FloatRange::Skewed{min:20.,max:20000.,factor:FloatRange::skew_factor(-2.3)}).with_unit(" Hz"),gain:FloatParam::new(format!("Band {} Gain",i+1),0.,FloatRange::Linear{min:-18.,max:18.}).with_unit(" dB"),q:FloatParam::new(format!("Band {} Q",i+1),0.707,FloatRange::Skewed{min:0.15,max:12.,factor:FloatRange::skew_factor(-1.5)}),kind:EnumParam::new(format!("Band {} Type",i+1),match i{0=>FilterKind::LowCut,1=>FilterKind::LowShelf,4=>FilterKind::HighShelf,5=>FilterKind::HighCut,_=>FilterKind::Bell})})} } }
impl Default for EmberEq { fn default()->Self {Self{params:Arc::new(EmberParams::default()),sample_rate:44100.,left:std::array::from_fn(|_|Biquad::default()),right:std::array::from_fn(|_|Biquad::default())}} }
impl EmberEq { fn update_filters(&mut self){for i in 0..6{let b=&self.params.bands[i];let k=match b.kind.value(){FilterKind::Bell=>BiquadKind::Peak,FilterKind::LowShelf=>BiquadKind::LowShelf,FilterKind::HighShelf=>BiquadKind::HighShelf,FilterKind::LowCut=>BiquadKind::HighPass,FilterKind::HighCut=>BiquadKind::LowPass};let c=Biquad::coefficients(k,self.sample_rate,b.frequency.value(),b.gain.value(),b.q.value());self.left[i].set_coefficients(c);self.right[i].set_coefficients(c);}} }
impl Plugin for EmberEq { const NAME:&'static str="Ember EQ";const VENDOR:&'static str="Cove Labs";const URL:&'static str="https://github.com/oxlenn/ember-eq";const EMAIL:&'static str="";const VERSION:&'static str=env!("CARGO_PKG_VERSION");const AUDIO_IO_LAYOUTS:&'static[AudioIOLayout]=&[AudioIOLayout{main_input_channels:NonZeroU32::new(2),main_output_channels:NonZeroU32::new(2),..AudioIOLayout::const_default()},AudioIOLayout{main_input_channels:NonZeroU32::new(1),main_output_channels:NonZeroU32::new(1),..AudioIOLayout::const_default()}];const MIDI_INPUT:MidiConfig=MidiConfig::None;const MIDI_OUTPUT:MidiConfig=MidiConfig::None;type SysExMessage=();type BackgroundTask=();fn params(&self)->Arc<dyn Params>{self.params.clone()} fn initialize(&mut self,_:&AudioIOLayout,c:&BufferConfig,_:&mut impl InitContext<Self>)->bool{self.sample_rate=c.sample_rate;self.update_filters();true} fn reset(&mut self){for f in self.left.iter_mut().chain(self.right.iter_mut()){f.reset();}} fn process(&mut self,buffer:&mut Buffer,_:&mut AuxiliaryBuffers,_:&mut impl ProcessContext<Self>)->ProcessStatus{if self.params.bypass.value(){return ProcessStatus::Normal;}self.update_filters();for mut frame in buffer.iter_samples(){for(ch,s)in frame.iter_mut().enumerate(){let bank=if ch==0{&mut self.left}else{&mut self.right};let mut x=*s;for(i,f)in bank.iter_mut().enumerate(){if self.params.bands[i].enabled.value(){x=f.process(x);}}*s=x*util::db_to_gain(self.params.output_gain.smoothed.next());}}ProcessStatus::Normal} }
impl ClapPlugin for EmberEq {const CLAP_ID:&'static str="com.covelabs.ember-eq";const CLAP_DESCRIPTION:Option<&'static str>=Some("A warm six-band parametric EQ from Cove Labs.");const CLAP_MANUAL_URL:Option<&'static str>=None;const CLAP_SUPPORT_URL:Option<&'static str>=None;const CLAP_FEATURES:&'static[ClapFeature]=&[ClapFeature::AudioEffect,ClapFeature::Equalizer,ClapFeature::Stereo];}
impl Vst3Plugin for EmberEq {const VST3_CLASS_ID:[u8;16]=*b"CoveLabsEmberEQ01";const VST3_SUBCATEGORIES:&'static[Vst3SubCategory]=&[Vst3SubCategory::Fx,Vst3SubCategory::Tools];}
nih_export_clap!(EmberEq);nih_export_vst3!(EmberEq);
